        qianjiang, shenjiang, jianghui, yanzhihui, zhushahui, yinzhuahui, qiandan, danfen,
        zhehui, tuhong, zhuanhong, yaohong,
    ) + LookPackPlaces.all + LookLibrarySky.all + LookLibraryDawn.all + LookLibraryHour.all + LookLibraryTrees.all + LookLibraryShore.all + LookLibraryJade.all + LookLibraryPeak.all + LookLibraryField.all + LookLibraryMetal.all + LookLibraryCourt.all + LookLibrarySpring.all + LookLibraryPrint.all + LookLibraryCloth.all + LookLibrarySand.all + LookLibraryIncense.all + LookLibraryStem.all + LookLibraryTea.all + LookLibraryBoat.all + LookLibraryLamp.all + LookLibraryBird.all + LookLibraryBridge.all + LookLibraryWine.all + LookLibraryFish.all + LookLibraryAlley.all + LookLibraryPaper.all + LookLibraryInsect.all + LookLibraryTemple.all + LookLibraryKiln.all + LookLibraryHerb.all + LookLibraryGame.all + LookLibraryStar.all + LookLibraryRiver.all + LookLibraryOpera.all + LookLibraryLake.all + LookLibraryFarm.all + LookLibraryDish.all + LookLibraryPass.all + LookLibraryIsland.all + LookLibraryFurn.all + LookLibraryPort.all + LookLibraryOre.all + LookLibraryScript.all + LookLibraryKitchen.all + LookLibraryTile.all + LookLibraryPaint.all + LookLibrarySew.all + LookLibraryVeg.all + LookLibraryWear.all + LookLibraryVessel.all + LookLibraryLattice.all + LookLibraryYard.all + LookLibraryPot.all + LookLibraryLock.all + LookLibraryCloud.all + LookLibrarySalt.all + LookLibraryShop.all + LookLibraryWeather.all + LookLibraryGate.all + LookLibraryFlame.all + LookLibraryLoom.all + LookLibraryPearl.all + LookLibraryDrum.all + LookLibraryBell.all + LookLibraryLeather.all + LookLibraryInkstone.all + LookLibraryBanner.all + LookLibraryCave.all + LookLibraryCoin.all + LookLibraryBow.all + LookLibraryCart.all + LookLibrarySeal.all + LookLibraryWell.all + LookLibraryAgate.all + LookLibraryReed.all + LookLibraryBath.all + LookLibraryMask.all + LookLibraryMirror.all + LookLibraryLacquer.all + LookLibraryKnot.all + LookLibraryScale.all + LookLibraryCoral.all + LookLibraryHorn.all + LookLibraryAmber.all + LookLibraryInn.all + LookLibraryEnamel.all + LookLibraryComb.all + LookLibraryUmbrella.all + LookLibraryArmor.all + LookLibraryTurquoise.all + LookLibraryMill.all + LookLibraryBeacon.all + LookLibraryBamboo.all + LookLibrarySpice.all + LookLibraryDye.all + LookLibraryIce.all + LookLibraryMoss.all + LookLibraryBone.all + LookLibraryCanal.all + LookLibraryMaple.all + LookLibraryWillow.all + LookLibraryAbacus.all + LookLibraryCompass.all + LookLibraryFelt.all + LookLibraryNet.all + LookLibraryLotus.all + LookLibraryPlum.all + LookLibraryOrchid.all + LookLibraryChrys.all + LookLibraryPine.all + LookLibraryPeony.all + LookLibraryOsmanthus.all + LookLibraryCamellia.all + LookLibraryMulberry.all + LookLibraryHemp.all + LookLibraryCotton.all + LookLibraryWool.all + LookLibraryWisteria.all + LookLibraryGinkgo.all + LookLibraryPersimmon.all + LookLibraryPeach.all }

    // all 的 id 唯一（见 LookLibraryTest）；这里保留「首次出现」只是防回归的兜底。
    private val index: Map<String, Look> by lazy {
        buildMap { for (look in all) if (!containsKey(look.id)) put(look.id, look) }
    }

    fun byId(id: String): Look? = index[id]

    /**
     * 「智能 + 全部预设」的 id 顺序。左右滑动换配方每次都要求这个顺序，
     * 原来调用方每次手势都 `all.map { it.id }` 现算 5446 项——在库里算一次就够了。
     */
    val idOrder: List<String> by lazy { listOf(AUTO_ID) + all.map { it.id } }

    /** 批量一瞬的选片行：`(id, 显示名)`，含「智能」。同样是算一次给所有重组用。 */
    val pickerChips: List<Pair<String, String>> by lazy {
        listOf(AUTO_ID to "智能") + all.map { it.id to it.name }
    }
}
